const categories=['Tất cả','Văn phòng','Học tập','Sáng tạo','Lập trình'];
let currentConcept='A',toastTimer;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
function locationState(){const raw=location.hash.slice(1)||'/home',split=raw.indexOf('?');return {path:split<0?raw:raw.slice(0,split),params:new URLSearchParams(split<0?'':raw.slice(split+1))};}
function href(path,params={}){return '#'+path+'?'+new URLSearchParams({...params,v:currentConcept});}
function notify(message){const n=document.getElementById('notice');n.textContent=message;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),5000);}
function searchBox(value=''){return `<form class="search-form" data-search role="search"><span class="search-icon" aria-hidden="true">⌕</span><label class="visually-hidden" for="search-input">Bạn muốn làm gì?</label><input id="search-input" name="q" type="search" value="${esc(value)}" placeholder="Bạn muốn làm gì hôm nay?" autocomplete="off"><button class="button" type="submit">Tìm kiếm <span aria-hidden="true">↗</span></button></form>`;}
function row(r,i){return `<a class="resource-row" href="${href('/resource/'+r.id)}"><span class="resource-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div><h3>${r.name}</h3><p>${r.summary}</p><div class="resource-meta"><span>${r.category}</span><span>${r.platform.slice(0,2).join(' / ')}${r.platform.length>2?' +':''}</span><span>${r.price}</span></div></div><span class="row-arrow" aria-hidden="true">↗</span></a>`;}
function home(){return `<div class="wrap"><section class="hero"><p class="eyebrow">CÔNG CỤ TỐT. CUỘC SỐNG GỌN HƠN.</p><h1>${currentConcept==='A'?'Tìm đúng công cụ.<br><span>Dành thời gian cho điều hay.</span>':'Công cụ bạn cần.<br><span>Trong một lần tìm.</span>'}</h1><p>Một thư viện tài nguyên số bằng tiếng Việt.<br>Để học tốt hơn, làm nhẹ hơn và khám phá nhiều hơn.</p></section>${searchBox()}<div class="search-hints"><span>Thử tìm:</span><a href="${href('/discover',{q:'chuyển file'})}">chuyển file</a><a href="${href('/discover',{q:'ghi bài giảng'})}">ghi bài giảng</a><a href="${href('/discover',{q:'ngoại ngữ'})}">học ngoại ngữ</a></div><div class="categories" aria-label="Khám phá theo nhu cầu">${categories.map((c,i)=>`<a class="chip ${i===0?'active':''}" href="${href('/discover',i?{category:c}:{})}">${i?c:'Khám phá tất cả ↗'}</a>`).join('')}</div><section aria-labelledby="curated-heading"><div class="section-head"><div><h2 id="curated-heading">${currentConcept==='A'?'Một vài lựa chọn đáng xem.':'Bắt đầu từ những công cụ này.'}</h2><p>Gợi ý biên tập minh họa · 8 tài nguyên mẫu</p></div><a class="text-link" href="${href('/discover')}">Xem tất cả <span aria-hidden="true">↗</span></a></div><div class="editorial-grid"><a class="feature-panel" href="${href('/resource/localsend')}"><p class="eyebrow">GÓC LÀM VIỆC · 01</p><h3>Chuyển tệp.<br>Giữ mọi thứ<br>đơn giản.</h3><p>Một công cụ nhỏ để các thiết bị<br>của bạn làm việc cùng nhau.</p><span class="feature-art" aria-hidden="true">A↗B</span><div class="feature-bottom"><strong>LocalSend</strong><span>Khám phá công cụ ↗</span></div></a><div class="resource-list">${resources.slice(currentConcept==='A'?1:0,5).map(row).join('')}</div></div></section><section class="principle"><h2>Chọn lọc, thay vì chất đống.</h2><p>Tìm theo việc bạn muốn làm, đọc mô tả dễ hiểu và đi thẳng đến nguồn chính thức. Mỗi tài nguyên cần thông tin về nền tảng, chi phí và điều kiện sử dụng — để bạn có cơ sở tự lựa chọn.</p></section></div>`;}
function discover(params){const q=params.get('q')||'',category=params.get('category')||'Tất cả',platform=params.get('platform')||'Tất cả',price=params.get('price')||'Tất cả',sort=params.get('sort')||'editorial';let matched=resources.filter(r=>(category==='Tất cả'||r.category===category)&&(platform==='Tất cả'||r.platform.includes(platform))&&(price==='Tất cả'||r.price===price)&&normalize([r.name,r.summary,r.tags,r.category].join(' ')).includes(normalize(q)));if(sort==='name')matched.sort((a,b)=>a.name.localeCompare(b.name,'vi'));if(sort==='rating')matched.sort((a,b)=>((b.votes*b.rating+20*4.5)/(b.votes+20))-((a.votes*a.rating+20*4.5)/(a.votes+20)));const options=(items,selected)=>items.map(x=>`<option ${x===selected?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('');return `<div class="wrap"><section class="page-heading"><p class="eyebrow">THƯ VIỆN TÀI NGUYÊN</p><h1>Tìm điều hữu ích.</h1><p>Từ một nhu cầu nhỏ đến một ý tưởng lớn. Bắt đầu bằng điều bạn muốn làm.</p></section>${searchBox(q)}<div class="discover-layout"><form class="filters" id="filters"><h2>Thu gọn lựa chọn</h2><label class="field">Nhu cầu<select name="category">${options(categories,category)}</select></label><label class="field">Nền tảng<select name="platform">${options(['Tất cả','Windows','macOS','Linux','Web','Android','iOS'],platform)}</select></label><label class="field">Chi phí<select name="price">${options(['Tất cả','Miễn phí','Có gói miễn phí','Tùy nền tảng'],price)}</select></label><a class="button secondary" href="${href('/discover')}">Xóa bộ lọc</a></form><section aria-label="Kết quả tìm kiếm"><div class="results-head"><span role="status">${matched.length} kết quả${q?' cho “'+esc(q)+'”':''}</span><label>Sắp xếp <select name="sort" id="sort">${[['editorial','Biên tập chọn'],['name','Tên A–Z'],['rating','Điểm mẫu có trọng số']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${matched.length?`<div class="resource-list">${matched.map(row).join('')}</div><p class="small-note">Dữ liệu thử giao diện. Điểm mẫu và số phiếu không phải đánh giá thật.${sort==='rating'?' Điểm mẫu Bayesian: C=4,5; m=20.':''}</p>`:`<div class="empty"><p class="eyebrow">THỬ MỘT CÁCH TÌM KHÁC</p><h2>Chưa tìm thấy tài nguyên phù hợp.</h2><p>Thử từ khóa ngắn hơn hoặc bỏ bớt bộ lọc.<br>Ví dụ: “chuyển file”, “văn bản”, “học tập”.</p><a class="button secondary" href="${href('/discover')}">Xem toàn bộ thư viện</a></div>`}</section></div></div>`;}
function detail(id){const r=resources.find(x=>x.id===id);if(!r)return `<div class="wrap page-heading"><h1>Không tìm thấy tài nguyên.</h1><a class="button" href="${href('/discover')}">Về thư viện</a></div>`;return `<div class="wrap"><div class="breadcrumb"><a href="${href('/discover')}">Thư viện</a><span aria-hidden="true">/</span><a href="${href('/discover',{category:r.category})}">${r.category}</a><span aria-hidden="true">/</span><span>${r.name}</span></div><section class="detail-hero"><div><p class="eyebrow">${r.type} · ${r.category}</p><h1>${r.name}</h1><p class="lead">${r.summary}</p><a class="button" href="${r.url}" target="_blank" rel="noopener noreferrer">Đến trang chính thức <span aria-hidden="true">↗</span></a><p class="small-note">Bạn sẽ đến website của nhà phát triển.<br>Kiểm tra phiên bản và điều khoản tại nguồn trước khi sử dụng.</p><div class="review-demo"><strong>${r.rating.toFixed(1)} <span aria-hidden="true">/ 5</span></strong><span>${r.votes} đánh giá mẫu · không phải số liệu thật</span></div></div><aside class="detail-facts" aria-label="Thông tin nhanh"><dl><div><dt>Nền tảng</dt><dd>${r.platform.join(', ')}</dd></div><div><dt>Chi phí minh họa</dt><dd>${r.price}</dd></div><div><dt>Giấy phép</dt><dd>${r.license}</dd></div><div><dt>Phù hợp với</dt><dd>${r.audience}</dd></div><div><dt>Kiểm chứng</dt><dd>Fixture P00 · chưa dùng thử</dd></div></dl></aside></section><div class="detail-content"><article class="article"><section><h2>Dùng để làm gì?</h2><p>${r.benefit}</p></section><section><h2>Trước khi bắt đầu</h2><p>${r.limit}</p><ul><li>Đọc hướng dẫn và yêu cầu thiết bị trên trang chính thức.</li><li>Kiểm tra giấy phép của bản phân phối và các tiện ích đi kèm.</li><li>Không tải bản cài từ nút quảng cáo hoặc nguồn không rõ ràng.</li></ul></section><section><h2>Minh bạch về nội dung</h2><p>Đây là bài minh họa bố cục Phase 00, chưa phải bài đánh giá đã biên tập. Chưa xác minh phiên bản, chi phí, giấy phép hay thử cài đặt. Khi vận hành thật, mỗi nhận định cần nguồn và ngày kiểm tra.</p></section></article><aside><div class="callout"><h2>Một nguồn, nhiều góc nhìn.</h2><p>Thông tin nguồn và bài biên tập sẽ hiển thị riêng với đánh giá cộng đồng. Điểm cao không phải bảo chứng an toàn.</p><button class="button secondary" data-report>Báo thông tin cần kiểm tra</button><p id="report-status" role="status"></p></div></aside></div></div>`;}
function admin(){return `<div class="wrap"><section class="page-heading"><p class="eyebrow">STUDIO BIÊN TẬP · MÔ PHỎNG UX</p><h1>Từ đường dẫn đến bản nháp.</h1><p>Nhập nguồn. Xem gợi ý. Biên tập bằng hiểu biết của bạn.<br>Bản nháp chỉ có thể xuất bản sau khi con người duyệt.</p></section><ol class="step-list"><li class="active"><span>1</span> Nhập nguồn</li><li><span>2</span> Xem gợi ý</li><li><span>3</span> Biên tập & duyệt</li></ol><div class="admin-layout"><form class="admin-form" id="import-form"><h2>Thêm một nguồn mới</h2><p>Bản mẫu không lấy dữ liệu URL, không gọi AI và không lưu dữ liệu. Dùng link LocalSend để xem một bản nháp fixture.</p><label class="field">URL nguồn chính thức<input id="source-url" name="url" type="url" value="https://localsend.org/" required placeholder="https://..."></label><div class="form-actions"><button class="button" id="analyze-button" type="submit">Mô phỏng phân tích <span aria-hidden="true">↗</span></button></div><p id="import-status" class="status-line" role="status" aria-live="polite"></p><div id="draft-fields" class="draft-fields" hidden><p class="eyebrow">BẢN NHÁP AI MẪU · CẦN BIÊN TẬP</p><label class="field">Tên tài nguyên<input id="draft-title" value="LocalSend" maxlength="120"></label><label class="field">Mô tả ngắn<textarea id="draft-summary" maxlength="700">Gửi tệp giữa các thiết bị trong cùng mạng nội bộ.</textarea></label><label class="field">Nhu cầu<select id="draft-category">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Bằng chứng giấy phép<input id="draft-evidence" placeholder="URL điều khoản / LICENSE cần kiểm tra"></label><p class="small-note">Nguồn fixture: https://localsend.org/ · chưa fetch · provider: mô phỏng Gemini. Giấy phép và nền tảng cần kiểm tra thủ công.</p><label class="check-row"><input type="checkbox" id="reviewed">Tôi đã xem thông tin nguồn trong bản mẫu. Đây chưa phải xác nhận đủ điều kiện xuất bản thật.</label><div class="form-actions"><button class="button secondary" type="button" id="preview-draft">Xem trước bản nháp</button><button class="button" type="button" id="save-draft" disabled>Đánh dấu chờ duyệt</button></div></div></form><aside><div class="preview-box" id="draft-preview"><p class="eyebrow">BẢN XEM TRƯỚC</p><h2>Ý tưởng bắt đầu từ một đường dẫn.</h2><p>Sau bước phân tích mô phỏng, bản nháp xuất hiện ở đây. Bạn có thể sửa tên, nội dung và phân loại trước khi chuyển sang hàng đợi duyệt.</p></div><p class="small-note">Luồng thật dự kiến: kiểm URL → chống trùng → lấy metadata có giới hạn → AI tạo nháp → admin sửa → kiểm quyền → duyệt. Không có nút xuất bản hoạt động trong P00.</p></aside></div></div>`;}
function render(){const {path,params}=locationState();currentConcept=params.get('v')==='B'?'B':'A';document.body.classList.toggle('concept-b',currentConcept==='B');document.getElementById('concept').value=currentConcept;document.getElementById('navigation').classList.remove('open');document.querySelector('.menu-button').setAttribute('aria-expanded','false');document.getElementById('main').innerHTML=path==='/discover'?discover(params):path.startsWith('/resource/')?detail(path.slice(10)):path==='/admin'?admin():home();document.querySelectorAll('.site-header a,.site-footer a').forEach(a=>{const raw=a.getAttribute('href').slice(1).split('?'),p=new URLSearchParams(raw[1]||'');p.set('v',currentConcept);a.setAttribute('href','#'+raw[0]+'?'+p);if(a.closest('nav')&&raw[0]===path)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=(path==='/discover'?'Khám phá':path==='/admin'?'Studio biên tập':path.startsWith('/resource/')?(resources.find(r=>r.id===path.slice(10))?.name||'Tài nguyên'):'Thư viện công cụ số')+' · Nếp · Prototype '+currentConcept;window.scrollTo(0,0);}
function showDraft(){document.getElementById('draft-preview').innerHTML=`<p class="eyebrow">${esc(document.getElementById('draft-category').value)} · BẢN NHÁP MẪU</p><h2>${esc(document.getElementById('draft-title').value||'Chưa có tên')}</h2><p>${esc(document.getElementById('draft-summary').value)}</p><a href="https://localsend.org/" target="_blank" rel="noopener noreferrer">localsend.org ↗</a><p>Giấy phép: cần xác minh<br>Trạng thái: chưa xuất bản</p>`;}
document.addEventListener('submit',event=>{if(event.target.matches('[data-search]')){event.preventDefault();location.hash=href('/discover',{q:new FormData(event.target).get('q').trim()});}if(event.target.id==='import-form'){event.preventDefault();document.getElementById('draft-fields').hidden=true;document.getElementById('reviewed').checked=false;document.getElementById('save-draft').disabled=true;document.getElementById('draft-preview').innerHTML='<p class=eyebrow>BẢN XEM TRƯỚC</p><p>Đang kiểm tra nguồn fixture. Chưa có bản nháp cho nguồn mới.</p>';const status=document.getElementById('import-status');let parsed;try{parsed=new URL(document.getElementById('source-url').value);}catch{status.textContent='Hãy nhập một URL hợp lệ.';return;}if(parsed.protocol!=='https:'||parsed.username||parsed.password){status.textContent='Dùng URL https không có thông tin đăng nhập.';return;}if(!['localsend.org','www.localsend.org'].includes(parsed.hostname)){status.textContent='P00 chỉ có fixture LocalSend. Dùng https://localsend.org/ để xem luồng; không URL nào được truy cập.';return;}status.textContent='Phân tích mô phỏng hoàn tất. Bản nháp cần kiểm tra nguồn và giấy phép.';document.getElementById('draft-fields').hidden=false;document.querySelectorAll('.step-list li').forEach((li,i)=>li.classList.toggle('active',i===1));showDraft();}});
document.addEventListener('change',event=>{if(event.target.id==='concept'){const {path,params}=locationState();params.set('v',event.target.value);location.hash='#'+path+'?'+params;}if(event.target.closest('#filters')||event.target.id==='sort'){const {params}=locationState();for(const [k,v] of new FormData(document.getElementById('filters')))params.set(k,v);params.set('sort',document.getElementById('sort').value);location.hash='#/discover?'+params;}if(event.target.id==='reviewed')document.getElementById('save-draft').disabled=!event.target.checked;});
document.addEventListener('click',event=>{if(event.target.closest('.menu-button')){const open=document.getElementById('navigation').classList.toggle('open');document.querySelector('.menu-button').setAttribute('aria-expanded',String(open));}if(event.target.closest('[data-report]'))document.getElementById('report-status').textContent='Mô phỏng: báo cáo sẽ vào hàng đợi quản trị. Chưa gửi thông tin nào.';if(event.target.id==='preview-draft'){showDraft();notify('Bản xem trước đã cập nhật trong trang.');}if(event.target.id==='save-draft'&&document.getElementById('reviewed').checked){showDraft();document.getElementById('import-status').textContent='Đã đánh dấu chờ duyệt trong phiên mô phỏng. Chưa lưu hoặc xuất bản.';document.querySelectorAll('.step-list li').forEach((li,i)=>li.classList.toggle('active',i===2));notify('Bản nháp đang chờ duyệt · mô phỏng, không lưu dữ liệu.');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.getElementById('navigation').classList.remove('open');document.querySelector('.menu-button').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{render();document.getElementById('main').focus({preventScroll:true});});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();document.getElementById('main').focus();});
render();

